// Shared pieces

const baseRevision = z
  .number()
  .int()
  .nonnegative()
  .describe('The revision the caller read; a stale value is rejected with 409');
const revision = z.number().int().nonnegative();
const theme = z.enum(['light', 'dark']);
const themes = z.array(theme).min(1).describe('One or both themes');
const slideIdsOrAll = z
  .union([z.literal('all'), z.array(slugSchema).min(1)])
  .describe("Slide ids, or 'all'");
const slotSchema = z.enum([...SLOT_NAMES, 'plate']);

export const outlineSchema = z.array(
  z.strictObject({
    id: slugSchema,
    name: z.string(),
    slides: z.array(
      z.strictObject({
        id: slugSchema,
        n: z.number().int().positive(),
        title: z.string(),
        kind: z.enum(SLIDE_KINDS),
      }),
    ),
  }),
);

export const slideResultSchema = z.strictObject({
  slide: slideSchema,
  revision,
  findings: z.array(findingSchema),
});

const layoutId = z.enum(LAYOUT_IDS).describe('One of the layout list (gslides-parity SPEC 5.2)');
const slideIdList = z.array(slugSchema).min(1).describe('One or more slide ids');

const slideListRow = z.strictObject({
  id: slugSchema,
  n: z.number().int().positive(),
  section: slugSchema,
  title: z.string(),
  kind: z.enum(SLIDE_KINDS),
  lint: z.strictObject({ s3: z.number().int().nonnegative(), s2: z.number().int().nonnegative() }),
  /** true for a skipped slide (gslides-parity SPEC 7.2.1) */
  skip: z.boolean().optional(),
  /** the layout the slide was made from, when written (gslides-parity SPEC 7.2.2) */
  template: layoutId.optional(),
  /** true for a canvas slide, a content slide on the freeform layout (gslides-parity SPEC-2 0.93) */
  canvas: z.boolean().optional(),
  /** the top level block count of a canvas slide */
  objects: z.number().int().nonnegative().optional(),
});

export const viewStateSchema = z.strictObject({
  slideId: slugSchema,
  n: z.number().int().positive(),
  mode: z.enum(['slide', 'grid', 'book']),
  theme,
  present: z.boolean(),
  edit: z.boolean().optional(),
  /** the stage scale, or 'fit' (gslides-parity SPEC 7.2.16) */
  zoom: z.union([z.number().positive(), z.literal('fit')]).optional(),
  /** the stage's scroll offset in stage px after a zoom (gslides-parity SPEC-2 0.81) */
  scroll: z.strictObject({ x: z.number(), y: z.number() }).optional(),
});

/** The list levels 1 to 9 (gslides-parity SPEC-2 0.58). */
const listLevel = z.number().int().min(1).max(LIST_LEVEL_MAX);

/** A plain text range in a Text, `[start, end]` counted in characters with one per paragraph break. */
const textRange = z
  .tuple([z.number().int().nonnegative(), z.number().int().nonnegative()])
  .describe(
    'The range in the plain text of the Text, [start, end], one character per paragraph break',
  );

const textPath = z.string().describe('JSON pointer of the Text inside the block, such as /text');

/** A grid cell as [row, column], zero based. */
const gridCell = z.tuple([z.number().int().nonnegative(), z.number().int().nonnegative()]);

/** A shape id: one of the five legacy ids, the 135 presets or the line kinds (blocks.ts SHAPE_KINDS). */
const shapeKind = z
  .string()
  .refine(
    (value) => (SHAPE_KINDS as ReadonlyArray<string>).includes(value),
    'a shape id from the shape picker',
  );

const closedShape = z
  .string()
  .refine((value) => isClosedShapeKind(value), 'a closed shape preset from the shape picker');

const connectEnd = z.strictObject({
  block: blockIdSchema,
  site: z.number().int().nonnegative().describe("The index of the target's connection site"),
});

/** The diagram templates of gslides-parity SPEC-2 2.8.3 (diagrams.ts DIAGRAM_TEMPLATES, B5). */
export const DIAGRAM_KINDS = [
  'grid',
  'hierarchy',
  'timeline',
  'process',
  'relationship',
  'cycle',
] as const;
export type DiagramKind = (typeof DIAGRAM_KINDS)[number];
export const DIAGRAM_STYLES = ['outline', 'plate', 'ink'] as const;
export type DiagramStyle = (typeof DIAGRAM_STYLES)[number];

/** The picture of a guide list write (gslides-parity SPEC-2 2.10). */
const guideAxis = z.enum(['x', 'y']).describe('x for a vertical guide, y for a horizontal one');

/** The objects of one converted slide, as slide.toCanvas reports them. */
const canvasObjectRow = z.strictObject({
  id: blockIdSchema,
  type: z.string(),
  pos: positionObjectSchema,
});

/** One deck of the deck list (gslides-parity SPEC 7.5 deck.list): the manifest facts, newest first. */
export const deckHeadSchema = z.strictObject({
  id: slugSchema,
  title: z.string(),
  slides: z.number().int().nonnegative(),
  sections: z.number().int().nonnegative(),
  revision: z.number().int().nonnegative(),
  updatedAt: z.string(),
  createdAt: z.string(),
  /** set when the deck is in the trash; such rows appear only with includeTrashed */
  trashedAt: z.string().optional(),
});

const deckTrashState = z.strictObject({
  id: slugSchema,
  /** the trash stamp, or null when the deck is not in the trash */
  trashedAt: z.string().nullable(),
  revision,
});

const empty = z.strictObject({});

const plateSide = z
  .enum(PLATE_SIDES)
  .describe('The plate rectangle the metrics are screened against');

/**
 * The two-tone parameters a capture or an intake takes before the pipeline fills the fixed
 * fields (kind, autocontrast 0.5, cell 2, bayer 8, lanczos3) and the crop default of the whole
 * source; every field is optional so `--black 24` alone is a complete request (SPEC 5.4).
 */
export const twoToneParamsSchema = z.strictObject({
  crop: z
    .tuple([z.number(), z.number(), z.number(), z.number()])
    .optional()
    .describe('Left, top, right, bottom in source pixels; may reach past the source'),
  channel: z.enum(['gray', 'r', 'g', 'b']).optional(),
  invert: z.boolean().optional(),
  blur: z.number().nonnegative().optional(),
  black: z.number().min(0).max(255).optional(),
  white: z.number().min(0).max(255).optional(),
  gamma: z.number().positive().optional(),
  minFilter: z.number().positive().optional(),
  polarity: z.enum(['dark-ground', 'light-ground']).optional(),
});

/** One asset's dither report: the twins, the metrics and the verification counts. */
export const ditherResultSchema = z.strictObject({
  assetId: slugSchema,
  twins: assetTwinsSchema,
  metrics: assetMetricsSchema.optional(),
  /** Cells of a screen regenerated from the source that differ from the committed dark twin. */
  mismatchedCells: z.number().int().nonnegative().optional(),
  /** Cells where the committed light twin is not the inverse of the dark one. */
  twinInverseMismatch: z.number().int().nonnegative().optional(),
  /** The recorded treatment lacks a parameter the pipeline needs, so it could not be re-run. */
  missingParameter: z.boolean().optional(),
  /** No continuous source is on disk (sourceFile absent), so the cells were not re-run. */
  missingSource: z.boolean().optional(),
  /** The committed twin files are not on disk, so nothing was read back. */
  missingTwins: z.boolean().optional(),
  /** Files written under assets/, relative to the deck directory. */
  written: z.array(z.string()),
});

/**
 * What deck.create starts from: the GT brand template record under decks/templates/gt-brand
 * (the deck's manifest and slides with a template.json naming it), or one title slide.
 */
export const DECK_TEMPLATES = ['gt-brand', 'blank'] as const;
export type DeckTemplateId = (typeof DECK_TEMPLATES)[number];

/**
 * The deck bundle shapes (docs/deck-transfer.md): what deck.pack reports, what deck.unpack and
 * deck.pull take and report; deck.push reports the same with the editor URL on the studio.
 */
const bundleCounts = z.strictObject({
  slides: z.number().int().nonnegative(),
  assets: z.number().int().nonnegative(),
  versions: z.number().int().nonnegative(),
  documents: z.number().int().nonnegative(),
});

export const bundlePackResultSchema = z.strictObject({
  deckId: slugSchema,
  title: z.string(),
  revision,
  out: z.string().describe('The zip written'),
  bytes: z.number().int().nonnegative(),
  sha256: z.string(),
  counts: z.strictObject({
    documents: z.number().int().nonnegative(),
    assets: z.number().int().nonnegative(),
    versions: z.number().int().nonnegative(),
  }),
});

export const bundleUnpackInputSchema = z.strictObject({
  file: z.string().describe('The bundle zip to read'),
  as: slugSchema.optional().describe('The deck id to write under; the bundle id when absent'),
  replace: z
    .boolean()
    .optional()
    .describe('Remove the deck that holds the id first; without it a taken id gets a free sibling'),
});

export const bundleUnpackResultSchema = z.strictObject({
  deckId: slugSchema.describe('The id the deck was written under'),
  sourceDeckId: slugSchema.describe('The id the bundle carried'),
  title: z.string(),
  revision,
  dir: z.string().describe('The deck directory'),
  replaced: z.boolean(),
  renamed: z.boolean(),
  counts: bundleCounts,
});

const A = ALL_TRANSPORTS;
const noWindow: ReadonlyArray<Transport> = ['cli', 'mcp', 'http'];

function action(spec: ActionSpec): ActionSpec {
  return spec;
}

